// Normaliza o sinal do CLP e dispara SOMENTE na borda de subida (pallet chegou).
const CFG = {
    ORDER_ID: "OP-2026-001",
    STATION: "MONTAGEM",
    DEBOUNCE_MS: 5000,
    TOPIC_OUT: "smart40/n2/montagem/pallet"
};

function toBool(v) {
    if (typeof v === "boolean") return v;
    if (typeof v === "number") return v !== 0;
    if (typeof v === "string") {
        const s = v.trim().toLowerCase();
        if (["1", "true", "on", "high"].includes(s)) return true;
        if (["0", "false", "off", "low"].includes(s)) return false;
    }
    return null;
}

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === "string") {
    const s = p.trim();
    try { p = JSON.parse(s); } catch (e) { p = s; }
}

let presence = null, tag = null, simulate = false, order = null;
if (p !== null && typeof p === "object") {
    const v = (p.presence !== undefined) ? p.presence
            : (p.pallet !== undefined) ? p.pallet
            : (p.value !== undefined) ? p.value
            : (p.state !== undefined) ? p.state
            : p.sensor;
    presence = toBool(v);
    tag = p.tag_uid || null;
    order = p.order_id || null;
    simulate = p.simulate === true;
} else {
    presence = toBool(p);
}

if (presence === null) {
    node.warn("Sinal do CLP não reconhecido: " + JSON.stringify(msg.payload));
    return null;
}

const now = Date.now();
const prev = flow.get("pallet_presence") === true;
flow.set("pallet_presence", presence);

if (!presence) {
    node.status({ fill: "grey", shape: "ring", text: "pallet ausente" });
    return null;
}
if (prev && !simulate) {
    node.status({ fill: "grey", shape: "dot", text: "presença mantida (sem nova borda)" });
    return null;
}
const last = flow.get("pallet_last_ts") || 0;
if (!simulate && (now - last) < CFG.DEBOUNCE_MS) {
    node.warn("Debounce: nova chegada em " + (now - last) + " ms ignorada");
    return null;
}
flow.set("pallet_last_ts", now);

const correlationId = "PALLET-" + now.toString(36) + "-" + Math.random().toString(36).slice(2, 8);
const out = {
    event: "PALLET_ARRIVED",
    station: CFG.STATION,
    order_id: order || CFG.ORDER_ID,
    correlation_id: correlationId,
    ts: new Date(now).toISOString(),
    source: msg.topic || "nodered"
};
if (tag) out.tag_uid = tag;

node.status({ fill: "green", shape: "dot", text: "PALLET_ARRIVED " + correlationId });
return { topic: CFG.TOPIC_OUT, payload: out, qos: 1, retain: false };

// Resume o resultado da inspeção publicado pela API do cobot (via amq.topic -> MQTT).
const e = msg.payload;
if (!e || typeof e !== "object") { return null; }
const ok = e.resultado === "INSPECTED_OK";
node.status({
    fill: ok ? "green" : "red",
    shape: "dot",
    text: (e.qrCode || "?") + " " + (ok ? "OK" : "NOK") + " -> " + (e.acao || "?")
});
const n = (flow.get("inspections_total") || 0) + 1;
const nok = (flow.get("inspections_nok") || 0) + (ok ? 0 : 1);
flow.set("inspections_total", n);
flow.set("inspections_nok", nok);
msg.summary = { total: n, nok: nok, last: e };
return msg;

// Processa comandos vindos de POST /api/v1/cobot/gripper/command (via CloudAMQP amq.topic -> smart40/n2/cobot/gripper)
const cmd = msg.payload || {};
const commandName = cmd.gripper_command || cmd.command || "EGH Grip";
const posMm = (cmd.position_mm !== undefined) ? Number(cmd.position_mm) : 18.5;
const forcePct = (cmd.force_percentage !== undefined) ? Number(cmd.force_percentage) : 50;
const ledColor = cmd.led_color || (commandName === "EGH Release" ? "BLUE" : "GREEN");

let state = "HOLDING";
if (commandName === "EGH Release" || posMm >= 75) state = "OPEN";
else if (posMm <= 4) state = "CLOSED";

flow.set("gripper_state", {
    model: "SCHUNK EGH80",
    state: state,
    position_mm: posMm,
    opening_percentage: Math.round((posMm / 80.0) * 1000) / 10,
    force_percentage: forcePct,
    led_color: ledColor,
    last_command: commandName,
    updated_at: new Date().toISOString()
});

node.status({
    fill: ledColor === "RED" ? "red" : (ledColor === "BLUE" ? "blue" : (ledColor === "YELLOW" ? "yellow" : "green")),
    shape: "dot",
    text: `${commandName} -> ${state} (${posMm}mm, ${forcePct}%)`
});

// Saída pronta para ligar ao nó IO-Link / Modbus / HTTP da garra física no Node-RED
msg.gripper_hw = {
    command: commandName,
    target_position_mm: posMm,
    force_percentage: forcePct,
    led_color: ledColor,
    state: state
};
return msg;
